mapper.select:
SELECT x.turn_id,x.thread_id,x.state,x.mutation_version,x.requested_at_ms,x.updated_at_ms, x.completed_at_ms,x.terminal_summary,x.error_code,x.error_message,x.cancel_requested_at_ms,x.cancel_reason, x.cancel_thread_revision,x.cancel_turn_mutation_version, x.input_queue_revision,x.is_accepting_inputs, NULL AS thread_revision,c.change_set_json,x.is_current_path,x.source_message_id, (SELECT tm.item_id FROM ja_conversation_timeline_entry tm JOIN ja_conversation_message m ON m.message_id=tm.item_id WHERE tm.turn_id=x.turn_id AND tm.thread_id=x.thread_id AND tm.kind='FINAL_ANSWER' ORDER BY m.ordinal DESC LIMIT 1) AS terminal_message_id FROM ja_conversation_turn x LEFT JOIN ja_turn_change_set c ON c.turn_id=x.turn_id WHERE x.thread_id=#{threadId} AND ( x.turn_sequence=(SELECT MAX(latest.turn_sequence) FROM ja_conversation_turn latest WHERE latest.thread_id=#{threadId}) OR x.turn_id=(SELECT pending.turn_id FROM ja_conversation_turn pending WHERE pending.thread_id=#{threadId} AND pending.state IN ('QUEUED','RUNNING','WAITING_APPROVAL','WAITING_INPUT','SUSPENDED') ORDER BY pending.turn_sequence LIMIT 1)
OR x.turn_id IN #{turnId}
) ORDER BY x.turn_sequence
